sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    var emailList = "";

    // Query the SPOC mapping table
    var spoc = new GlideRecord('x_1647027_candid_0_spoc_mapping');  // replace with your actual table name if different
    spoc.addQuery('technology', current.technology); // match the technology of the candidate
    spoc.query();

    if (spoc.next()) {
        emailList = spoc.spoc_email.toString(); // replace 'spoc_email' with the actual field name for SPOC email
    }

    return emailList;
})(current, template, email, email_action, event);
